public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class FloorBoundaryReportR10 {public string state="RUNNING";public List<RoofRow> runs=new List<RoofRow>();}
 [UnityTest]public IEnumerator R10FloorBoundary(){var report=new FloorBoundaryReportR10();Directory.CreateDirectory(Evidence);var path=Path.Combine(Evidence,"floor-boundary.json");Assert.That(File.Exists(path),Is.False);Action save=()=>File.WriteAllText(path,JsonUtility.ToJson(report,true));save();
 foreach(var original in new[]{new RoofSpec{name="base-standard",angle=12,power=100},new RoofSpec{name="base-low",angle=12,power=70},new RoofSpec{name="base-high",angle=28,power=100},new RoofSpec{name="base-left",angle=12,power=100,direction=-1},new RoofSpec{name="roof-grown",angle=65,power=100,level=2}})foreach(bool fix in new[]{false,true}){var spec=JsonUtility.FromJson<RoofSpec>(JsonUtility.ToJson(original));spec.name+=(fix?"-repair":"-reference");yield return NewRetrySubject(spec.reduced,true,spec.gate);var physicalWorld=Field(current,"world");physicalWorld.GetType().GetField("UseFloorContactSteps").SetValue(physicalWorld,fix);Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=spec.angle,power=spec.power,direction=spec.direction,upgradeLevel=spec.level}));var aim=JsonUtility.ToJson(new Aim{angle=spec.angle,power=spec.power,direction=spec.direction});var work=JsonUtility.ToJson(new Work{direction=spec.direction});Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",work);Call(current,"Tick",1f/60);}Call(current,"ReleaseLaunch",aim);var row=new RoofRow{input=spec,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.runs.Add(row);save();
 for(int i=0;i<6500&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);var final=State(current);row.final=JsonUtility.ToJson(final);row.stopped=(bool)Property(current,"Finished");row.ceilingExited=(bool)Field(final,"ceilingExited");save();Assert.That((string)Field(final,"physicsFault"),Is.Empty,spec.name);Assert.That(row.stopped,Is.True,spec.name);if(spec.level==2)Assert.That(row.ceilingExited,Is.True,spec.name);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}
}
